#!/usr/bin/env python3
"""run_case.py <dir> <port> [outfile]  -- start server on dir, drive session, dump, kill."""
import sys, os, re, subprocess, time, signal, urllib.request, urllib.parse

d = os.path.abspath(sys.argv[1]); port = int(sys.argv[2])
out = sys.argv[3] if len(sys.argv) > 3 else os.path.join(d, "_dump.txt")
BASE = "http://127.0.0.1:%d" % port

log = open(os.path.join(d, "_server.log"), "w")
p = subprocess.Popen(["/workspace/executable", "drill", d, "--port", str(port),
                      "--open-browser", "false", "--bury-siblings", "false"],
                     stdout=log, stderr=subprocess.STDOUT)
def get(path="/"):
    with urllib.request.urlopen(BASE + path) as r: return r.read().decode("utf-8", "replace")
def post(a):
    req = urllib.request.Request(BASE + "/", data=urllib.parse.urlencode({"action": a}).encode(), method="POST")
    with urllib.request.urlopen(req) as r: return r.status

ok = False
for _ in range(60):
    try:
        get("/"); ok = True; break
    except Exception: time.sleep(0.25)
res = []
if not ok:
    res.append("!!! SERVER DID NOT START !!!")
    log.close(); res.append(open(os.path.join(d, "_server.log")).read())
else:
    def blk(h):
        m = re.search(r'<div class="card-container">(.*?)</div><div class="controls">', h, re.S)
        return m.group(1) if m else None
    for i in range(300):
        h = get("/"); b = blk(h)
        if b is None:
            res.append("=== SESSION END ==="); break
        res.append("### %d Q ###\n%s" % (i, b))
        post("Reveal")
        b2 = blk(get("/"))
        res.append("### %d A ###\n%s" % (i, b2))
        post("Good")
    try: post("End")
    except Exception: pass
    p.terminate()
try: p.wait(timeout=5)
except Exception: p.kill()
open(out, "w").write("\n".join(res) + "\n")
print(open(out).read())

